args.command:
cat > ~/dose.py <<'EOF'
import workcell, sys
tare = float(sys.argv[1])
def read():
    r = workcell.call("scale","read")
    return float(r.text.split()[3])
def dose(kind):
    workcell.call("robot","dose",kind)
while True:
    net = read() - tare
    rem = 250.0 - net
    print(f"net {net:.2f} rem {rem:.2f}")
    if rem < -0.10:
        workcell.call("robot","remove"); continue
    if -0.10 <= rem <= 0.15:
        break
    if rem > 60: dose("bulk")
    elif rem > 12: dose("coarse")
    elif rem > 0.4: dose("fine")
    else: dose("micro")
print("final net", read()-tare)
EOF
python3 ~/dose.py 119.57

